const ArgumentType = require('../../extension-support/argument-type');
const BlockType = require('../../extension-support/block-type')
const formatMessage = require('format-message');
const PlayGo = require('./playgo.js')

const blockIconURI = 'data:image/svg+xml;base64,';

/**
 * Enum for tilt sensor direction.
 * @readonly
 * @enum {string}
 */
const PlayGoTiltDirection = {
    FRONT: 'front',
    BACK: 'back',
    LEFT: 'left',
    RIGHT: 'right',
    ANY: 'any'
};

/**
 * Enum for PlayGo gestures.
 * @readonly
 * @enum {string}
 */
const PlayGoGestures = {
    MOVED: 'moved',
    SHAKEN: 'shaken',
    JUMPED: 'jumped'
};

const PlayGoButtons = {
    A: 'A',
    B: 'B',
    ANY: 'any'
};

const PlayGoMotors = {
    M1p: 'M1+',
    M1m: 'M1-',
    M2p: 'M2+',
    M2m: 'M2-'
};

const PlayGoGPIO = {
    GPIO0: 'GPIO0',
    GPIO1: 'GPIO1',
    GPIO2: 'GPIO2',
    GPIO3: 'GPIO3'
};

/**
 * Enum for micro:bit pin states.
 * @readonly
 * @enum {string}
 */
const PlayGoPinState = {
    ON: 'on',
    OFF: 'off'
};

/*
* Clase que crea los bloques, con sus argumentos y menus
* @author ibrahdz
*
*/
class Scratch3PlayGoBlocks{
    /**
     * @return {string} - the name of this extension.
     */
    static get EXTENSION_NAME () {
        return 'PlayGo';
    }
    /**
     * @return {string} - the ID of this extension.
     */
    static get EXTENSION_ID () {
        return 'playgo';
    }
    /**
     * @return {array} - text and values for each buttons menu element
     */
    get BUTTONS_MENU () {
        return [
            {text: 'A', value: PlayGoButtons.A},
            {text: 'B', value: PlayGoButtons.B},
            {text: 'any', value: PlayGoButtons.ANY}
        ];
    }

     /**
     * @return {array} - text and values for each gestures menu element
     */
    get GESTURES_MENU () {
        return [
            {
                text: formatMessage({
                    id: 'microbit.gesturesMenu.moved',
                    default: 'moved',
                    description: 'label for moved gesture in gesture picker for micro:bit extension'
                }),
                value: PlayGoGestures.MOVED
            },
            {
                text: formatMessage({
                    id: 'microbit.gesturesMenu.shaken',
                    default: 'shaken',
                    description: 'label for shaken gesture in gesture picker for micro:bit extension'
                }),
                value: PlayGoGestures.SHAKEN
            },
            {
                text: formatMessage({
                    id: 'microbit.gesturesMenu.jumped',
                    default: 'jumped',
                    description: 'label for jumped gesture in gesture picker for micro:bit extension'
                }),
                value: PlayGoGestures.JUMPED
            }
        ];
    }

    /**
     * @return {array} - text and values for each pin state menu element
     */
    get PIN_STATE_MENU () {
        return [
            {
                text: formatMessage({
                    id: 'microbit.pinStateMenu.on',
                    default: 'on',
                    description: 'label for on element in pin state picker for micro:bit extension'
                }),
                value: PlayGoPinState.ON
            },
            {
                text: formatMessage({
                    id: 'microbit.pinStateMenu.off',
                    default: 'off',
                    description: 'label for off element in pin state picker for micro:bit extension'
                }),
                value: PlayGoPinState.OFF
            }
        ];
    }

    /**
     * @return {array} - text and values for each tilt direction menu element
     */
    get TILT_DIRECTION_MENU () {
        return [
            {
                text: formatMessage({
                    id: 'microbit.tiltDirectionMenu.front',
                    default: 'front',
                    description: 'label for front element in tilt direction picker for micro:bit extension'
                }),
                value: PlayGoTiltDirection.FRONT
            },
            {
                text: formatMessage({
                    id: 'microbit.tiltDirectionMenu.back',
                    default: 'back',
                    description: 'label for back element in tilt direction picker for micro:bit extension'
                }),
                value: PlayGoTiltDirection.BACK
            },
            {
                text: formatMessage({
                    id: 'microbit.tiltDirectionMenu.left',
                    default: 'left',
                    description: 'label for left element in tilt direction picker for micro:bit extension'
                }),
                value: PlayGoTiltDirection.LEFT
            },
            {
                text: formatMessage({
                    id: 'microbit.tiltDirectionMenu.right',
                    default: 'right',
                    description: 'label for right element in tilt direction picker for micro:bit extension'
                }),
                value: PlayGoTiltDirection.RIGHT
            }
        ];
    }

    /**
     * @return {array} - text and values for each tilt direction (plus "any") menu element
     */
    get TILT_DIRECTION_ANY_MENU () {
        return [
            ...this.TILT_DIRECTION_MENU,
            {
                text: formatMessage({
                    id: 'microbit.tiltDirectionMenu.any',
                    default: 'any',
                    description: 'label for any direction element in tilt direction picker for micro:bit extension'
                }),
                value: PlayGoTiltDirection.ANY
            }
        ];
    }

    /**
     * @return {array} - text and values for each motors menu element
     */
    get MOTORS_MENU () {
        return [
            {text: 'M1+', value: PlayGoMotors.M1p},
            {text: 'M1-', value: PlayGoMotors.M1m},
            {text: 'M2+',value: PlayGoMotors.M2p},
            {text: 'M2-',value: PlayGoMotors.M2m}
        ];
    }

    /**
     * @return {array} - text and values for each gpio
     */
    get GPIO_MENU () {
        return [
            {text: 'GPIO0', value: PlayGoGPIO.GPIO0},
            {text: 'GPIO1', value: PlayGoGPIO.GPIO1},
            {text: 'GPIO2', value: PlayGoGPIO.GPIO2},
            {text: 'GPIO3', value: PlayGoGPIO.GPIO3}
        ];
    }

    constructor (runtime) {
        this.runtime = runtime
        this._peripheral = new PlayGo(runtime, Scratch3PlayGoBlocks.EXTENSION_ID)
    }
    
    getInfo () {
        return {
            id: Scratch3PlayGoBlocks.EXTENSION_ID,
            name: Scratch3PlayGoBlocks.EXTENSION_NAME,
            blockIconURI: blockIconURI,
            menuIconURI: blockIconURI,
            showStatusButton: true,
            blocks: [
                /* Bloques creados por Ibraim, 12 Feb 2025
                */
                {
                    opcode: 'evBoton',
                    text: "al presional el botón [BTN]",
                    blockType: BlockType.HAT,
                    arguments: {
                        BTN: {
                            type: ArgumentType.STRING,
                            menu: 'buttons',
                            defaultValue: PlayGoButtons.A
                        }
                    }
                },
                {
                    opcode: 'isButtonPressed',
                    text: formatMessage({
                        id: 'microbit.isButtonPressed',
                        default: '[BTN] button pressed?',
                        description: 'is the selected button on the micro:bit pressed?'
                    }),
                    blockType: BlockType.BOOLEAN,
                    arguments: {
                        BTN: {
                            type: ArgumentType.STRING,
                            menu: 'buttons',
                            defaultValue: PlayGoButtons.A
                        }
                    }
                },
                '---',
                {
                    opcode: 'whenGesture',
                    text: formatMessage({
                        id: 'microbit.whenGesture',
                        default: 'when [GESTURE]',
                        description: 'when the selected gesture is detected by the micro:bit'
                    }),
                    blockType: BlockType.HAT,
                    arguments: {
                        GESTURE: {
                            type: ArgumentType.STRING,
                            menu: 'gestures',
                            defaultValue: PlayGoGestures.MOVED
                        }
                    }
                },
                '---',
                {
                    opcode: 'displaySymbol',
                    text: formatMessage({
                        id: 'microbit.displaySymbol',
                        default: 'display [MATRIX]',
                        description: 'display a pattern on the micro:bit display'
                    }),
                    blockType: BlockType.COMMAND,
                    arguments: {
                        MATRIX: {
                            type: ArgumentType.MATRIX,
                            defaultValue: '0101010101100010101000100'
                        }
                    }
                },
                {
                    opcode: 'displayText',
                    text: formatMessage({
                        id: 'microbit.displayText',
                        default: 'display text [TEXT]',
                        description: 'display text on the micro:bit display'
                    }),
                    blockType: BlockType.COMMAND,
                    arguments: {
                        TEXT: {
                            type: ArgumentType.STRING,
                            defaultValue: formatMessage({
                                id: 'microbit.defaultTextToDisplay',
                                default: 'Hello!',
                                description: `default text to display.
                                IMPORTANT - the micro:bit only supports letters a-z, A-Z.
                                Please substitute a default word in your language
                                that can be written with those characters,
                                substitute non-accented characters or leave it as "Hello!".
                                Check the micro:bit site documentation for details`
                            })
                        }
                    }
                },
                {
                    opcode: 'displayClear',
                    text: formatMessage({
                        id: 'microbit.clearDisplay',
                        default: 'clear display',
                        description: 'display nothing on the micro:bit display'
                    }),
                    blockType: BlockType.COMMAND
                },
                '---',
                {
                    opcode: 'whenTilted',
                    text: formatMessage({
                        id: 'microbit.whenTilted',
                        default: 'when tilted [DIRECTION]',
                        description: 'when the micro:bit is tilted in a direction'
                    }),
                    blockType: BlockType.HAT,
                    arguments: {
                        DIRECTION: {
                            type: ArgumentType.STRING,
                            menu: 'tiltDirectionAny',
                            defaultValue: PlayGoTiltDirection.ANY
                        }
                    }
                },
                {
                    opcode: 'isTilted',
                    text: formatMessage({
                        id: 'microbit.isTilted',
                        default: 'tilted [DIRECTION]?',
                        description: 'is the micro:bit is tilted in a direction?'
                    }),
                    blockType: BlockType.BOOLEAN,
                    arguments: {
                        DIRECTION: {
                            type: ArgumentType.STRING,
                            menu: 'tiltDirectionAny',
                            defaultValue: PlayGoTiltDirection.ANY
                        }
                    }
                },
                {
                    opcode: 'getTiltAngle',
                    text: formatMessage({
                        id: 'microbit.tiltAngle',
                        default: 'tilt angle [DIRECTION]',
                        description: 'how much the micro:bit is tilted in a direction'
                    }),
                    blockType: BlockType.REPORTER,
                    arguments: {
                        DIRECTION: {
                            type: ArgumentType.STRING,
                            menu: 'tiltDirection',
                            defaultValue: PlayGoTiltDirection.FRONT
                        }
                    }
                },
                '---',
                {
                    opcode: 'rpPotenciometro',
                    text: "valor del potenciometro",
                    blockType: BlockType.REPORTER,
                },
                {
                    opcode: 'rpMicrofono',
                    text: "valor del microfono",
                    blockType: BlockType.REPORTER,
                },
                {
                    opcode: 'rpFotocelda',
                    text: "valor de la fotocelda",
                    blockType: BlockType.REPORTER,
                },
                '---',
                {
                    opcode: 'cmLED',
                    text: "encender LED [LED]",
                    blockType: BlockType.COMMAND,
                    arguments: {
                        LED: {
                            type: ArgumentType.STRING,
                            menu: 'motors',
                            defaultValue: PlayGoMotors.M1p
                        },
                    }
                },
                {
                    opcode: 'cmBuzzer',
                    text: "encender Buzzer",
                    blockType: BlockType.COMMAND,                    
                },
                '---',  
                {
                    opcode: 'cmGPIO',
                    text: "encender GPIO [GPIO]",
                    blockType: BlockType.COMMAND,
                    arguments: {
                        GPIO: {
                            type: ArgumentType.STRING,
                            menu: 'gpios',
                            defaultValue: PlayGoGPIO.GPIO0
                        },
                    }
                }, 
                {
                    opcode: 'rpGPIO',
                    text: "valor de GPIO [GPIO]",
                    blockType: BlockType.REPORTER,
                    arguments: {
                        GPIO: {
                            type: ArgumentType.STRING,
                            menu: 'gpios',
                            defaultValue: PlayGoGPIO.GPIO0
                        },
                    }
                },          
                {
                    opcode: 'whenPinConnected',
                    text: formatMessage({
                        id: 'microbit.whenPinConnected',
                        default: 'when pin [PIN] connected',
                        description: 'when the pin detects a connection to Earth/Ground'

                    }),
                    blockType: BlockType.HAT,
                    arguments: {
                        PIN: {
                            type: ArgumentType.STRING,
                            menu: 'touchPins',
                            defaultValue: '0'
                        }
                    }
                },
            ],
            menus: {
                buttons: {
                    acceptReporters: true,
                    items: this.BUTTONS_MENU
                },
                motors: {
                    acceptReporters: true,
                    items: this.MOTORS_MENU
                },
                gpios: {
                    acceptReporters: true,
                    items: this.GPIO_MENU
                },
                gestures: {
                    acceptReporters: true,
                    items: this.GESTURES_MENU
                },
                pinState: {
                    acceptReporters: true,
                    items: this.PIN_STATE_MENU
                },
                tiltDirection: {
                    acceptReporters: true,
                    items: this.TILT_DIRECTION_MENU
                },
                tiltDirectionAny: {
                    acceptReporters: true,
                    items: this.TILT_DIRECTION_ANY_MENU
                },
                touchPins: {
                    acceptReporters: true,
                    items: ['0', '1', '2']
                }
            }
        }
    }
    rpFotocelda = () => this._peripheral.value;
    evBotonA = () => this._peripheral.isBtnPressed();
    rpPotenciometro = () => this._peripheral.temp;
}
module.exports = Scratch3PlayGoBlocks;
